            text-decoration: underline;
        }

        .verify-btn {
            width: 100%;
            height: 50px;
            background-color: #007acc;
            color: #ffffff;
            font-size: 16px;
            font-weight: 600;
            border: none;
            border-radius: 10px;
            cursor: pointer;
            transition: background-color 0.3s;
