<body>
    <div class="container">
        <h1 class="title">أدخل الرمز</h1>
        <p class="subtitle">لقد أرسلنا رمزًا مكوّنًا من 6 أرقام إلى +966 55 123 4567</p>

        <div class="code-container">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
            <input type="text" maxlength="1" class="code-box" inputmode="numeric">
        </div>

        <div class="resend-container">
            <span class="resend-text">إعادة الإرسال خلال <span id="countdown">0:45</span></span>
        </div>

        <button class="verify-btn" id="verifyBtn">تحقق</button>
    </div>

    <script>
        // Countdown timer
        let timeLeft = 45;
        const countdownEl = document.getElementById('countdown');

        function updateCountdown() {
            const minutes = Math.floor(timeLeft / 60);
            const seconds = timeLeft % 60;
            countdownEl.textContent = `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
            if (timeLeft > 0) {
                timeLeft--;
                setTimeout(updateCountdown, 1000);
            }
        }

        updateCountdown();

        // Auto-focus and move between code boxes
        const codeBoxes = document.querySelectorAll('.code-box');
        codeBoxes.forEach((box, index) => {
            box.addEventListener('input', () => {
                if (box.value.length === 1 && index < codeBoxes.length - 1) {
                    codeBoxes[index + 1].focus();
                }
            });

            box.addEventListener('keydown', (e) => {
                if (e.key === 'Backspace' && index > 0 && !box.value) {
                    codeBoxes[index - 1].focus();
                }
            });
        });

        // Verify button functionality
        const verifyBtn = document.getElementById('verifyBtn');
        verifyBtn.addEventListener('click', () => {
            const code = Array.from(codeBoxes).map(box => box.value).join('');
            if (code.length === 6) {
                alert(`تم إدخال الرمز: ${code}`);
            } else {
                alert('يرجى إدخال الرمز الكامل');
            }
        });
    </script>
</body>
</html>
